def schedule_flowshop(times: list[list[int]]) -> list[int]:
    import math
    import random

    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]

    def compute_makespan(perm):
        """Compute makespan for a given permutation."""
        if not perm:
            return 0
        # C[j][k] = completion time of job perm[j] on machine k
        C = [[0] * m for _ in range(len(perm))]
        for j, job in enumerate(perm):
            for k in range(m):
                if j == 0 and k == 0:
                    C[j][k] = times[job][k]
                elif j == 0:
                    C[j][k] = C[j][k-1] + times[job][k]
                elif k == 0:
                    C[j][k] = C[j-1][k] + times[job][k]
                else:
                    C[j][k] = max(C[j-1][k], C[j][k-1]) + times[job][k]
        return C[-1][-1]

    def compute_makespan_with_completions(perm):
        """Compute makespan and return completion matrix."""
        if not perm:
            return 0, []
        C = [[0] * m for _ in range(len(perm))]
        for j, job in enumerate(perm):
            for k in range(m):
                if j == 0 and k == 0:
                    C[j][k] = times[job][k]
                elif j == 0:
                    C[j][k] = C[j][k-1] + times[job][k]
                elif k == 0:
                    C[j][k] = C[j-1][k] + times[job][k]
                else:
                    C[j][k] = max(C[j-1][k], C[j][k-1]) + times[job][k]
        return C[-1][-1], C

    def insert_job_makespan(perm, job, pos):
        """Compute makespan when inserting job at position pos in perm."""
        new_perm = perm[:pos] + [job] + perm[pos:]
        return compute_makespan(new_perm)

    def best_insertion_position(perm, job):
        """Find best position to insert job into perm."""
        best_ms = float('inf')
        best_pos = 0
        for pos in range(len(perm) + 1):
            ms = insert_job_makespan(perm, job, pos)
            if ms < best_ms:
                best_ms = ms
                best_pos = pos
        return best_pos, best_ms

    # Priority metrics for ordering jobs
    def total_time(job):
        return sum(times[job])

    def front_back_ratio(job):
        # Jobs with more work on front machines first (helps pipeline)
        half = m // 2
        front = sum(times[job][k] for k in range(half))
        back = sum(times[job][k] for k in range(half, m))
        return back - front  # higher back means insert later

    # NEH heuristic: sort by decreasing total processing time, then insert greedily
    def neh_heuristic(job_order):
        """NEH algorithm with given initial ordering."""
        schedule = []
        for job in job_order:
            pos, _ = best_insertion_position(schedule, job)
            schedule.insert(pos, job)
        return schedule

    # Sort jobs by decreasing total processing time (standard NEH)
    jobs_by_total = sorted(range(n), key=lambda j: -total_time(j))

    # Also try sorting by different criteria
    jobs_by_front_heavy = sorted(range(n), key=lambda j: -(sum(times[j][k] for k in range(m//2 + 1))))
    jobs_by_back_heavy = sorted(range(n), key=lambda j: -(sum(times[j][k] for k in range(m//2, m))))

    best_schedule = None
    best_makespan = float('inf')

    # Try NEH with different orderings
    for ordering in [jobs_by_total, jobs_by_front_heavy, jobs_by_back_heavy]:
        sched = neh_heuristic(ordering)
        ms = compute_makespan(sched)
        if ms < best_makespan:
            best_makespan = ms
            best_schedule = sched[:]

    # Local search: try to improve with swap and insertion moves
    def local_search(schedule, time_limit_iters=500):
        current = schedule[:]
        current_ms = compute_makespan(current)
        improved = True
        iters = 0
        while improved and iters < time_limit_iters:
            improved = False
            iters += 1
            # Try all pairwise swaps
            for i in range(len(current)):
                for j in range(i+1, len(current)):
                    current[i], current[j] = current[j], current[i]
                    ms = compute_makespan(current)
                    if ms < current_ms:
                        current_ms = ms
                        improved = True
                    else:
                        current[i], current[j] = current[j], current[i]
        return current, current_ms

    def local_search_insertion(schedule, time_limit_iters=200):
        """Try reinserting each job at a better position."""
        current = schedule[:]
        current_ms = compute_makespan(current)
        improved = True
        iters = 0
        while improved and iters < time_limit_iters:
            improved = False
            iters += 1
            for i in range(len(current)):
                job = current[i]
                remaining = current[:i] + current[i+1:]
                pos, ms = best_insertion_position(remaining, job)
                if ms < current_ms:
                    current = remaining[:pos] + [job] + remaining[pos:]
                    current_ms = ms
                    improved = True
                    break  # restart
        return current, current_ms

    # Apply local search to best schedule
    if n <= 50:
        best_schedule, best_makespan = local_search(best_schedule, time_limit_iters=300)

    best_schedule, best_makespan = local_search_insertion(best_schedule, time_limit_iters=300)

    # For small instances, try more aggressive search
    if n <= 20:
        # Try random restarts with NEH
        for _ in range(10):
            shuffled = list(range(n))
            random.shuffle(shuffled)
            sched = neh_heuristic(shuffled)
            sched, ms = local_search_insertion(sched, time_limit_iters=100)
            if ms < best_makespan:
                best_makespan = ms
                best_schedule = sched[:]

    # Final insertion local search pass
    best_schedule, best_makespan = local_search_insertion(best_schedule, time_limit_iters=500)

    return best_schedule

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    import random

    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]

    def compute_makespan(perm):
        # C[k] = completion time on machine k for current job
        C = [0] * m
        for j in perm:
            C[0] = C[0] + times[j][0]
            for k in range(1, m):
                C[k] = max(C[k], C[k-1]) + times[j][k]
        return C[m-1]

    def compute_completion_times(perm):
        # Returns full completion time matrix
        comp = [[0]*m for _ in range(len(perm))]
        for i, j in enumerate(perm):
            if i == 0:
                comp[0][0] = times[j][0]
                for k in range(1, m):
                    comp[0][k] = comp[0][k-1] + times[j][k]
            else:
                comp[i][0] = comp[i-1][0] + times[j][0]
                for k in range(1, m):
                    comp[i][k] = max(comp[i-1][k], comp[i][k-1]) + times[j][k]
        return comp

    # NEH heuristic
    def neh():
        # Sort jobs by decreasing total processing time
        totals = [(sum(times[j]), j) for j in range(n)]
        totals.sort(reverse=True)
        order = [j for _, j in totals]

        # Incrementally build the sequence
        sequence = [order[0]]
        for i in range(1, n):
            job = order[i]
            best_ms = None
            best_pos = 0
            for pos in range(len(sequence) + 1):
                trial = sequence[:pos] + [job] + sequence[pos:]
                ms = compute_makespan(trial)
                if best_ms is None or ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            sequence = sequence[:best_pos] + [job] + sequence[best_pos:]
        return sequence

    # Build initial solution with NEH
    best_perm = neh()
    best_ms = compute_makespan(best_perm)

    # Local search: insertion moves (relocate single job)
    def insertion_improvement(perm, max_iter=None):
        perm = list(perm)
        n_jobs = len(perm)
        improved = True
        iterations = 0
        while improved:
            improved = False
            if max_iter is not None and iterations >= max_iter:
                break
            iterations += 1
            for i in range(n_jobs):
                job = perm[i]
                # Remove job from position i
                new_perm = perm[:i] + perm[i+1:]
                current_ms = compute_makespan(perm)
                best_local_ms = current_ms
                best_local_pos = i
                for pos in range(len(new_perm) + 1):
                    if pos == i:
                        continue
                    trial = new_perm[:pos] + [job] + new_perm[pos:]
                    ms = compute_makespan(trial)
                    if ms < best_local_ms:
                        best_local_ms = ms
                        best_local_pos = pos
                if best_local_ms < current_ms:
                    perm = new_perm[:best_local_pos] + [job] + new_perm[best_local_pos:]
                    improved = True
                    break
        return perm, compute_makespan(perm)

    # Apply insertion improvement with iteration cap
    max_iter = max(1, min(20, 200 // n)) if n > 0 else 5
    improved_perm, improved_ms = insertion_improvement(best_perm, max_iter=max_iter)
    if improved_ms < best_ms:
        best_perm = improved_perm
        best_ms = improved_ms

    # Adjacent swap improvement pass
    def adjacent_swap_improvement(perm, max_passes=5):
        perm = list(perm)
        n_jobs = len(perm)
        for _ in range(max_passes):
            improved = False
            for i in range(n_jobs - 1):
                # Swap adjacent jobs i and i+1
                perm[i], perm[i+1] = perm[i+1], perm[i]
                ms_new = compute_makespan(perm)
                if ms_new < compute_makespan(perm[:i] + [perm[i+1]] + [perm[i]] + perm[i+2:]):
                    improved = True
                else:
                    # Swap back
                    perm[i], perm[i+1] = perm[i+1], perm[i]
            if not improved:
                break
        return perm, compute_makespan(perm)

    # More efficient adjacent swap
    def fast_adjacent_swap(perm, max_passes=10):
        perm = list(perm)
        n_jobs = len(perm)
        current_ms = compute_makespan(perm)
        for _ in range(max_passes):
            improved = False
            for i in range(n_jobs - 1):
                perm[i], perm[i+1] = perm[i+1], perm[i]
                ms_new = compute_makespan(perm)
                if ms_new < current_ms:
                    current_ms = ms_new
                    improved = True
                else:
                    perm[i], perm[i+1] = perm[i+1], perm[i]
            if not improved:
                break
        return perm, current_ms

    swap_perm, swap_ms = fast_adjacent_swap(best_perm, max_passes=min(10, max(3, 50 // n)))
    if swap_ms < best_ms:
        best_perm = swap_perm
        best_ms = swap_ms

    # For small instances, do more thorough search
    if n <= 15:
        # Additional insertion pass
        improved_perm2, improved_ms2 = insertion_improvement(best_perm, max_iter=50)
        if improved_ms2 < best_ms:
            best_perm = improved_perm2
            best_ms = improved_ms2
        # Another swap pass
        swap_perm2, swap_ms2 = fast_adjacent_swap(best_perm, max_passes=20)
        if swap_ms2 < best_ms:
            best_perm = swap_perm2
            best_ms = swap_ms2

    return best_perm
